/* ============ 提示 ============ */
var toastTimer=null;
function toast(msg, actionLabel, actionFn){
  var t=$('toast'); t.innerHTML='';
  t.appendChild(document.createTextNode(msg));
  if (actionLabel){
    var b=document.createElement('button'); b.type='button'; b.textContent=actionLabel;
    b.onclick=function(){ hideToast(); actionFn&&actionFn(); };
    t.appendChild(b);
  }
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer=setTimeout(hideToast, actionLabel?7000:2800);
}
function hideToast(){ $('toast').classList.remove('show'); }

function renderSyncBar(){
  var bar=$('syncbar');
  if (!queue.length){ bar.classList.remove('show'); return; }
  bar.classList.add('show');
  $('syncText').textContent = '有 '+queue.length+' 项改动还没存到线上，点重试可以再来一次。';
}
$('syncRetry').onclick=function(){ retryQueue(); };
$('syncDrop').onclick=function(){
  queue=[]; renderSyncBar(); toast('已放弃这些未同步的改动'); render();
};
function retryQueue(){
  if (MODE !== 'db'){ toast('当前不是资料库模式，没有需要重试的线上改动'); return; }
  var items=queue.slice(); queue=[]; renderSyncBar();
  items.forEach(function(it){
    it.run().then(function(){
      toast('「'+it.label+'」已存好');
      if (it.key) refreshKey(it.key);
    }).catch(function(){
      queue.push(it);
    }).then(function(){ renderSyncBar(); render(); });
  });
}

/* ============ GitHub 同步状态指示器（左下角常驻小药丸） ============ */
var _ghStatusEl = null;
function setGhStatus(state){
  var el = _ghStatusEl || (_ghStatusEl = $('ghStatus'));
  if (!el) return;
  var map = {
    saving: ['正在保存…','saving'],
    synced: ['已同步到 GitHub','synced'],
    failed: ['保存失败','failed'],
    noconn: ['未连接云端（仅本地缓存）','noconn'],
    'local-only': ['仅本地保存（未连云端）','local'],
    localfile: ['已存到本地文件夹（直接写盘）','localfile'],
    db: ['资料库模式（云端）','db']
  };
  var s = map[state] || map.noconn;
  el.innerHTML = '<i class="dot"></i><span>'+s[0]+'</span>';
  el.className = 'ghstatus show ' + s[1];
}
function initGhStatus(){
  if (MODE === 'db'){ setGhStatus('db'); return; }
  if (MODE === 'localfile'){ setGhStatus('localfile'); return; }
  if (MODE === 'local'){ setGhStatus('local-only'); return; }
  /* gh 模式：有 Token 视为已连上（绿色），无 Token 仅本地缓存（灰） */
  setGhStatus((GH && GH.token) ? 'synced' : 'noconn');
}

/* ============ 读取 ============ */
function fetchAll(key, cb){
  if (MODE === 'localfile'){
    if (_ghCache){ cb(_ghCache[key] || []); return; }
    if (_ghLoading){ _ghLoading.push(function(all){ cb((all||{})[key] || []); }); return; }
    _ghLoading = [];
    loadLocalAll(function(obj){
      _ghCache = obj;
      var q = _ghLoading; _ghLoading = null;
      q.forEach(function(fn){ fn(_ghCache); });
      cb(obj[key] || []);
    });
    return;
  }
  if (MODE === 'gh'){
    if (_ghCache){ cb(_ghCache[key] || []); return; }
    if (_ghLoading){ _ghLoading.push(function(all){ cb((all||{})[key] || []); }); return; }
    _ghLoading = [];
    /* 先试静态直读（同域 fetch，无需 Token、不怕 api.github.com 超时）；
       拿不到分片数据再回退到原来的 API 逻辑。 */
    (async function(){
      var st = await ghStaticLoadV2();
      if (st && Object.keys(st).length){
        _ghCache = st;
        localCacheSetFrom(st);
        cb(st[key] || []);
        if (_ghLoading){ _ghLoading.forEach(function(fn){ fn(_ghCache); }); _ghLoading = null; }
        return;
      }
      ghGetAll(function(all, sha, err){
      var cache = localCacheGet();
      if (all === null && err){
        /* GitHub 读取失败（网络/401）：用本地缓存兜底全量，避免强刷后数据全失 */
        _ghCache = cache || {};
        cb(_ghCache[key] || []);
        if (_ghLoading){ _ghLoading.forEach(function(fn){ fn(_ghCache); }); _ghLoading = null; }
        return;
      }
      _ghCache = all || {};
      if (all && !err){
        /* 与本地缓存按 id 合并：防止「保存进行中强刷、GitHub 尚未落盘」导致的新增丢失。
           GitHub 为权威（同 id 以 GitHub 为准），本地有而 GitHub 缺失的 id 补回。 */
        var cache = localCacheGet();
        if (cache){
          Object.keys(cache).forEach(function(ck){
            var crows = (cache[ck] || []).filter(function(r){ return r && r._id; });
            if (!crows.length) return;
            var base = (_ghCache[ck] || []).slice();
            var has = {}; base.forEach(function(r){ if (r && r._id) has[String(r._id)] = true; });
            crows.forEach(function(r){ if (!has[String(r._id)]) base.push(r); });
            _ghCache[ck] = base;
          });
        }
        localCacheSetFrom(_ghCache); /* 合并结果写回本地缓存，保持最新 */
      }
      cb(_ghCache[key] || []);
      if (_ghLoading){ _ghLoading.forEach(function(fn){ fn(_ghCache); }); _ghLoading = null; }
    });
    })();
    return;
  }
  if (MODE === 'local'){ cb(lsGet(key)); return; }
  var all=[], cursor=null, guard=0;
  function page(){
    if (guard++ > 40){ cb(all); return; }
    T[key].page(cursor).then(function(r){
      all = all.concat(r && r.results ? r.results : []);
      if (r && r.hasMore && r.nextCursor){ cursor=r.nextCursor; page(); } else cb(all);
    }).catch(function(){ cb(null); });
  }
  page();
}
function loadAll(){
  var keys = ORDER.filter(function(k){ return k!=='overview'; }).concat(EXTRA);
  keys.forEach(function(k){
    store[k]={rows:[],status:'loading'};
    fetchAll(k, function(rows){
      if (rows===null){ store[k].status='error'; }
      else { store[k].rows=normalizeRows(rows); store[k].status= rows.length? 'ok' : 'empty'; }
      render();
    });
  });
  render();
}

/* ============ 写入 ============ */
function propsFrom(fields, vals){
  var p={};
  fields.forEach(function(f){
    if (f.t==='geopick') return;
    var v = vals[f.k];
    if (f.t==='text' || f.t==='textarea' || f.t==='dyn'){
      if (v!=='' && v!=null) p[f.k]={text:String(v)};
    } else if (f.t==='img'){
      if (v) p[f.k]={image:{images:[{title:f.k,imageUrl:String(v)}]}};
    } else if (f.t==='select'){
      if (v) p[f.k]={select:String(v)};
    } else if (f.t==='multi'){
      if (v && v.length) p[f.k]={multi_select:v};
    } else if (f.t==='date'){
      if (v) p[f.k]={date:String(v)};
    } else if (f.t==='number' || f.t==='stars'){
      p[f.k]={number:num(v)};
    } else if (f.t==='currency'){
      p[f.k]={currency:num(v)};
    } else if (f.t==='check'){
      p[f.k]={checkbox:!!v};
    }
  });
  return p;
}
/* 写入成功后立刻并入本地视图，再静默回拉一次线上做校对 */
function localUpsert(key, id, vals){
  if (!store[key]) return;
  var row={_id:id};
  MODS[key].fields.forEach(function(f){
    if (f.t==='geopick') return;
    var v=vals[f.k];
    if (f.t==='img') row[f.k] = v ? [{imageUrl:String(v)}] : null;
    else if (f.t==='multi') row[f.k] = (v && v.length) ? v : null;
    else if (f.t==='check') row[f.k] = !!v;
    else if (f.t==='stars' || f.t==='number' || f.t==='currency') row[f.k] = num(v);
    else if (f.t==='date') row[f.k] = v ? String(v) : null;
    else row[f.k] = (v===''||v==null) ? null : v;
  });
  var rows = store[key].rows.filter(function(r){ return String(r._id)!==String(id); });
  rows.unshift(row);
  store[key].rows = rows;
  store[key].status = rows.length ? 'ok' : 'empty';
  if (MODE === 'gh'){ queueGhSave(); localCacheSet(); }
  else if (MODE === 'localfile'){ queueLocalSave(); }
  else if (MODE === 'local'){ lsSet(key, rows); localCacheSet(); }
}
function refreshKey(key, after){
  fetchAll(key, function(rows){
    if (rows!==null){
      store[key].rows=normalizeRows(rows);
      store[key].status = rows.length?'ok':'empty';
      render();
    }
    if (after) after();
  });
}
function mutate(label, run, optimistic, key, after){
  if (MODE !== 'db'){
    toast('当前没连上线上数据，改动没能保存', '重试', function(){ mutate(label,run,optimistic,key,after); });
    return;
  }
  if (optimistic) optimistic();
  run().then(function(){
    queue = queue.filter(function(q){ return q.run!==run; });
    renderSyncBar();
    if (key) refreshKey(key, after);
    else if (after) after();
    render();
  }).catch(function(e){
    if (!queue.some(function(q){ return q.run===run; })) queue.push({label:label, run:run, key:key});
    renderSyncBar();
    toast('「'+label+'」没保存成功，已放进待同步', '重试', retryQueue);
    if (optimistic) render();
  });
}
function addRow(key, vals, after){
  if (MODE !== 'db'){
    var id = 'l_' + Date.now().toString(36) + Math.random().toString(36).slice(2,7);
    localUpsert(key, id, vals);
    if (after) after();
    render();
    toast(MODE === 'localfile' ? '已保存到本地 data 文件夹' : '已保存到本地（当前浏览器）');
    return;
  }
  var m=MODS[key], props=propsFrom(m.fields, vals);
  mutate('新增'+m.name, function(){
    return T[key].add(props).then(function(res){
      var id = res && (res.id || res.record_id || res._id);
      if (id) localUpsert(key, id, vals);
      return res;
    });
  }, null, key, after);
}
function updateRow(key, id, vals, after){
  if (MODE !== 'db'){
    localUpsert(key, id, vals);
    if (after) after();
    render();
    toast(MODE === 'localfile' ? '已保存到本地 data 文件夹' : '已保存到本地');
    return;
  }
  var m=MODS[key], props=propsFrom(m.fields, vals);
  mutate('修改'+m.name, function(){
    return T[key].upd(id, props).then(function(res){
      localUpsert(key, id, vals);
      return res;
    });
  }, null, key, after);
}
function deleteRow(key, id, name, after){
  if (MODE !== 'db'){
    store[key].rows = store[key].rows.filter(function(r){ return r._id!==id; });
    store[key].status = store[key].rows.length ? 'ok' : 'empty';
    if (MODE === 'gh'){ queueGhSave(); localCacheSet(); }
    else if (MODE === 'localfile'){ queueLocalSave(); }
    else { lsSet(key, store[key].rows); localCacheSet(); }
    if (after) after();
    render();
    toast('已从本地删除');
    return;
  }
  var m=MODS[key];
  mutate('删除「'+name+'」', function(){ return T[key].del(id); },
    function(){ store[key].rows = store[key].rows.filter(function(r){ return r._id!==id; }); }, key, after);
}

/* ============ 筛选 ============ */
function filtered(key){
  var rows = store[key].rows.slice(), f=ui[key]||{};
  var q = (f.q||'').trim().toLowerCase();
  if (key==='collection'){
    if (f.cat) rows=rows.filter(function(r){ return r['大类']===f.cat; });
    if (f.sub) rows=rows.filter(function(r){ return r['小类']===f.sub; });
    if (q) rows=rows.filter(function(r){
      return ((r['名称']||'')+' '+(r['IP']||'')+' '+(r['系列']||'')+' '+(r['编号']||'')+' '+(r['存储地点']||'')+' '+(r['购入渠道']||'')+' '+(r['短评']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){
      var na=parseInt(String(a['编号']||'').replace(/^[#＃]/,''),10);
      var nb=parseInt(String(b['编号']||'').replace(/^[#＃]/,''),10);
      if (!isNaN(na) && !isNaN(nb) && na!==nb) return na-nb;
      return dstr(b['购入日期']).localeCompare(dstr(a['购入日期']));
    });
  } else if (key==='travel'){
    if (f.status) rows=rows.filter(function(r){ return r['状态']===f.status; });
    if (q) rows=rows.filter(function(r){
      return ((r['地点']||'')+' '+(r['国家地区']||'')+' '+(r['备注']||'')).toLowerCase().indexOf(q)>=0; });
    var rank={'此生必去':0,'很想去':1,'顺路看看':2};
    rows.sort(function(a,b){
      var s={'想去':0,'去过':1};
      var d=(s[a['状态']]||0)-(s[b['状态']]||0);
      return d?d:((rank[a['心愿等级']]||1)-(rank[b['心愿等级']]||1));
    });
  } else if (key==='study'){
    if (f.field) rows=rows.filter(function(r){ return r['领域']===f.field; });
    if (q) rows=rows.filter(function(r){
      return ((r['计划']||'')+' '+(r['备注']||'')).toLowerCase().indexOf(q)>=0; });
    var ord={'进行中':0,'未开始':1,'已暂停':2,'已完成':3};
    rows.sort(function(a,b){ return (ord[a['状态']]||1)-(ord[b['状态']]||1); });
  } else if (key==='food'){
    if (f.type) rows=rows.filter(function(r){ return r['类型']===f.type; });
    if (q) rows=rows.filter(function(r){
      return ((r['名称']||'')+' '+(r['城市']||'')+' '+(r['短评']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){ return dstr(b['打卡日期']).localeCompare(dstr(a['打卡日期'])); });
  } else if (key==='idea'){
    if (f.cat) rows=rows.filter(function(r){ return r['分类']===f.cat; });
    if (f.star) rows=rows.filter(function(r){ return !!r['星标']; });
    if (q) rows=rows.filter(function(r){
      return ((r['内容']||'')+' '+(r['来源']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){ return dstr(b['记录日期']).localeCompare(dstr(a['记录日期'])); });
  }
  return rows;
}

/* ============ 小组件 ============ */
function stripHTML(key){
  var s=store[key];
  if (s.status==='loading') return '<span class="dot load"></span>正在从线上读取…';
  if (s.status==='error') return '<span class="dot err"></span>读取失败，数据没能拉回来 '+
    '<button class="btn link" type="button" data-act="reload" data-key="'+key+'">重试</button>';
  return '<span class="dot ok"></span>已同步 '+s.rows.length+' 条 · 数据在资料库里，换设备也在';
}
function emptyHTML(title, tip){
  return '<div class="empty"><b>'+esc(title)+'</b><span>'+esc(tip)+'</span></div>';
}
function statusPill(v){
  var map={'想看':0,'在看':1,'看完':2,'搁置':3,'想去':0,'去过':2,
    '待启程':0,'进行中':1,'已完成':2,'未开始':0,'已暂停':3,
    '想收':0,'已预订':1,'在库':2,'已出':3};
  var c = map[v]==null?0:map[v];
  return '<span class="pill s'+c+'">'+esc(v||'—')+'</span>';
}

/* ============ 各模块渲染 ============ */
/* 各模块封面 CDN + v13 各分类封面（侧栏/主页/藏品筛选共用；缺图时回退汉字 icon） */
var MOD_BG = {
  collection: 'images/museum-bg.png',                                                          /* v16.0：替换为无水印博物馆背景图 */
  travel:     'images/earth-cover.png',                                                        /* v15.18：基于 16K 颜色 + 4K 高程的地球封面 */
  av:         'images/opera-bg.png',                                                          /* v16.0：新模块「影音厅」用歌剧院背景 */
  study:      'images/study-bg.png',                                                          /* v15.19/v16.0：古典文渊斋（无水印） */
  food:       'images/mod_food.png',
  idea:       'images/idea-sky.png'                                                           /* v15.18：本地银河照片 */
};
function renderOverview(){
  var h='';
  var cards = [
    ['collection','藏'],['travel','旅'],['av','音'],['study','学'],['food','食'],['idea','感']
  ].map(function(p){
    var m=MODS[p[0]], s=store[p[0]];
    var n = s.status==='loading' ? '读取中' : (s.status==='error' ? '读取失败' : String(s.rows.length)+(m.unit||' 条'));
    var bg = MOD_BG[p[0]] || '';
    return '<button class="ovcard" type="button" data-act="go" data-key="'+p[0]+'"'+
      ' style="--ovbg:url(\''+bg+'\')">'+
      '<div class="ovcover" style="background-image:url(\''+bg+'\')"></div>'+
      '<div class="ovmask"></div>'+
      '<div class="ovbody"><em>'+esc(m.eyebrow||m.name)+'</em><b>'+esc(m.name)+'</b><span>'+esc(n)+'</span></div>'+
      '</button>';
  }).join('');
  h += '<section class="panel"><div class="panel-head"><div><h2>六个地方</h2>'+
    '<div class="hint">点一下进到某个模块</div></div></div><div class="ovgrid">'+cards+'</div></section>';

  /* 藏品概览 */
  var cs=store.collection, year=ui.year;
  var owned=cs.rows.filter(function(r){ return r['状态']==='在库'; });
  var bought=cs.rows.filter(function(r){ return yr(r['购入日期'])===year; });
  var spend=0; bought.forEach(function(r){ spend += num(r['购入价格']); });
  var byCat={}; cs.rows.forEach(function(r){ var k=r['大类']||'其他'; byCat[k]=(byCat[k]||0)+1; });
  var maxC=1; Object.keys(byCat).forEach(function(k){ if(byCat[k]>maxC) maxC=byCat[k]; });
  var ys={}; cs.rows.forEach(function(r){ var y=yr(r['购入日期']); if(y) ys[y]=1; }); ys[ui.year]=1;
  var ysel='<select id="yearSel" style="min-height:34px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:#fbf8f3;font-size:12px">'+
    Object.keys(ys).sort().reverse().map(function(y){
      return '<option value="'+y+'"'+(y===ui.year?' selected':'')+'>'+y+'</option>'; }).join('')+'</select>';

  h += '<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>'+year+' 年的藏品</h2>'+
    '<div class="hint">按购入日期统计</div></div>'+ysel+'</div>'+
    '<div class="statgrid">'+
      '<div class="stat"><u>在库</u><b>'+owned.length+'</b><i>件</i></div>'+
      '<div class="stat"><u>'+year+' 年入手</u><b>'+bought.length+'</b><i>件</i></div>'+
      '<div class="stat"><u>'+year+' 年投入</u><b>¥'+Math.round(spend)+'</b></div>'+
      '<div class="stat"><u>IP 数</u><b>'+store.ip.rows.length+'</b><i>个</i></div>'+
    '</div>';
  if (cs.rows.length){
    h += '<div class="barlist" style="margin-top:18px">'+CATS.map(function(k){
      if (!byCat[k]) return '';
      return '<div class="barrow"><span>'+k+'</span><div class="track"><div class="fill" style="width:'+
        Math.round(byCat[k]/maxC*100)+'%"></div></div><em>'+byCat[k]+'</em></div>';
    }).join('')+'</div>';
  } else {
    h += emptyHTML('还没有藏品','点「添加藏品」，从最近入手的那件开始。');
  }
  h += '</section>';

  /* 最近留下的 */
  var feed=[];
  function push(key, rows, dateF, titleF, subF){
    rows.forEach(function(r){
      var d=dstr(dateF(r)); if(!d) return;
      feed.push({d:d, key:key, title:titleF(r), sub:subF(r)});
    });
  }
  push('collection', store.collection.rows, function(r){return r['购入日期'];},
    function(r){return r['名称'];}, function(r){return '入手 · '+esc(r['大类']||'');});
  push('travel', store.travel.rows.filter(function(r){return r['状态']==='去过';}),
    function(r){return r['出行日期'];}, function(r){return r['地点'];}, function(r){return '去过 · '+(r['国家地区']||'');});
  push('food', store.food.rows, function(r){return r['打卡日期'];},
    function(r){return r['名称'];}, function(r){return (r['类型']||'')+' · '+stars(r['星级']);});
  push('idea', store.idea.rows, function(r){return r['记录日期'];},
    function(r){return String(r['内容']||'').slice(0,40);}, function(r){return '灵感 · '+(r['分类']||'');});
  feed.sort(function(a,b){ return b.d.localeCompare(a.d); });
  feed = feed.slice(0,12);
  h += '<section class="panel"><div class="panel-head"><div><h2>最近留下的</h2>'+
    '<div class="hint">跨模块按时倒序</div></div></div>';
  if (feed.length){
    h += '<div class="timeline">'+feed.map(function(f){
      return '<div class="tl"><time>'+esc(mdText(f.d))+'</time><div><b>'+esc(f.title)+'</b>'+
        '<span>'+f.sub+' · '+esc(MODS[f.key].name)+'</span></div></div>';
    }).join('')+'</div>';
  } else {
    h += emptyHTML('还没有动态','加几条记录，这里会长成一条时间线。');
  }
  h += '</section>';
  return h;
}

