  'China':1,'United States of America':1,'Russia':1,'Brazil':1,'Australia':1,'Canada':1,
  'India':1,'Argentina':1,'Mexico':1,'Indonesia':1,'Saudi Arabia':1,'Iran':1,'Mongolia':1,
  'France':1,'Spain':1,'Sweden':1,'Norway':1,'Finland':1,'Egypt':1,'South Africa':1,
  'Italy':1,'United Kingdom':1,'Germany':1,'Japan':1,'New Zealand':1,'Greenland':1,
  'Madagascar':1,'Kazakhstan':1,'Antarctica':1,'Thailand':1,'Vietnam':1,'Myanmar':1,
  'Malaysia':1,'Philippines':1,'Korea':1,'Ukraine':1,'Poland':1,'Greece':1,'Portugal':1,
  'Turkey':1,'Mexico':1,'Chile':1,'Peru':1,'Colombia':1,'Venezuela':1,
  'Ethiopia':1,'Kenya':1,'Tanzania':1,'Morocco':1,'Algeria':1,'Libya':1,'Mali':1,
