/* ============================================================
   藏品 · 大英博物馆阳光长廊（v16：背景透视走向 + 6 个玻璃展柜）
   ============================================================ */
/* 6 大类在展厅里按透视走向摆放：左侧手办/周边/杯盏、右侧毛绒/卡牌/着物
   每个展柜 = 玻璃罩（贴类目封面）+ 黑色类目标签；两者都跟随背景透视倾斜 */
function _museumCase(cat, side, depth, cnt){
  var cover = CAT_BG[cat] || '';
  return '<div class="mcase-persp '+side+' d'+depth+'" data-act="zone" data-v="'+esc(cat)+'" data-cat="'+esc(cat)+'"'+
         ' style="--cat-bg:url(\''+esc(cover)+'\')">'+
         '<div class="mcase-glass"></div>'+
         '<div class="mcase-nameplate">'+esc(cat)+' <em>'+cnt+'</em></div>'+
         '</div>';
}
function _avCase(cat, side, depth, cnt){
  var cover = CAT_BG[cat] || '';
  return '<div class="mcase-persp '+side+' d'+depth+'" data-act="avzone" data-v="'+esc(cat)+'"'+
         ' style="--cat-bg:url(\''+esc(cover)+'\')">'+
         '<div class="mcase-glass"></div>'+
         '<div class="mcase-nameplate">'+esc(cat)+' <em>'+cnt+'</em></div>'+
         '</div>';
}
function _renderPerspectiveCases(items, cats, sidePrefix, fn){
  var html = '';
  cats.forEach(function(cat, i){
    var arr = items.filter(function(r){ return r['大类']===cat; });
    var depth = 2 - i;   /* 越靠前（i 越小）depth 越大 */
    html += fn(cat, sidePrefix, depth, arr.length);
  });
  return html;
}
/* ============================================================
   藏品馆 · 所见即所得布局编辑器
   - 仅作用于第 1 层透视展厅的 6 个类目展柜
   - 布局以「相对 .museum-floor 的百分比」存储：{ 类目:{x,y,w} }
   - 优先 localStorage 持久化，失败则退化为内存变量（同一次会话内仍有效）
   ============================================================ */
var MUSEUM_LAYOUT = (function(){
  try {
    var o = JSON.parse(localStorage.getItem('life_desk_museum_layout_v1')) || {};
    /* 分类改名后，把旧类目名的布局搬到新名字上，避免之前调好的摆位失效 */
    var renamed = {'观影':'电影','音乐':'留声机','杯子':'杯盏','服装':'着物'};
    var out = {};
    Object.keys(o).forEach(function(k){ out[renamed[k] || k] = o[k]; });
    return out;
  } catch(e){ return {}; }
})();
function saveMuseumLayout(){
  try { localStorage.setItem('life_desk_museum_layout_v1', JSON.stringify(MUSEUM_LAYOUT)); } catch(e){}
}
/* 把 floor 内的每个展柜按 layout / 编辑态 应用定位与尺寸 */
function applyMuseumLayout(){
  var floor=document.querySelector('.museum-floor'); if(!floor) return;
  var editing = !!ui.collection.editing;
  var cases=[].slice.call(floor.querySelectorAll('.mcase-persp'));
  var hasLayout = cases.some(function(e){
    var c=e.getAttribute('data-cat')||e.getAttribute('data-v'); return !!MUSEUM_LAYOUT[c];
  });
  /* 先切 class，使 .museum-side 变 static、展柜的定位基准统一回到整层 floor（offsetParent=floor），再测量 */
  floor.classList.toggle('editing', editing);
  floor.classList.toggle('layouted', editing || hasLayout);
  cases.forEach(function(elm){
    var cat=elm.getAttribute('data-cat')||elm.getAttribute('data-v');
    if (editing){
      elm.style.right='auto'; elm.style.bottom='auto';
      if (MUSEUM_LAYOUT[cat]){
        var L=MUSEUM_LAYOUT[cat];
        elm.style.left=L.x+'%'; elm.style.top=L.y+'%'; elm.style.width=L.w+'%';
      } else {
        /* 首次进入编辑：用 offsetParent（=floor）换算百分比，保证「所见」不变、且与后续重应用一致 */
        var op=elm.offsetParent || floor;
        var w=elm.offsetWidth/op.clientWidth*100;
        elm.style.left=(elm.offsetLeft/op.clientWidth*100)+'%';
        elm.style.top=(elm.offsetTop/op.clientHeight*100)+'%';
        elm.style.width=w+'%';
      }
      elm.setAttribute('data-act','');               /* 编辑态禁止点击跳转 */
      if (!elm.querySelector('.mcase-resize')){
        var h=document.createElement('div'); h.className='mcase-resize'; h.setAttribute('data-resize','1');
        elm.appendChild(h);
      }
    } else {
      var rh=elm.querySelector('.mcase-resize'); if(rh) rh.remove();
      if (MUSEUM_LAYOUT[cat]){
        var L2=MUSEUM_LAYOUT[cat];
        elm.style.left=L2.x+'%'; elm.style.top=L2.y+'%'; elm.style.width=L2.w+'%';
        elm.style.right='auto'; elm.style.bottom='auto';
      }
      elm.setAttribute('data-act','zone');           /* 恢复跳转 */
    }
  });
  if (editing) attachMuseumDrag(floor);
}
/* 拖动移动 + 右下角缩放 */
function attachMuseumDrag(floor){
  var cases=[].slice.call(floor.querySelectorAll('.mcase-persp'));
  cases.forEach(function(elm){
    if (elm.__musBound) return; elm.__musBound=true;
    elm.addEventListener('pointerdown', function(e){
      if (e.target && e.target.classList && e.target.classList.contains('mcase-resize')) return;
      e.preventDefault();
      var fr=floor.getBoundingClientRect();
      var startX=e.clientX, startY=e.clientY;
      var sl=parseFloat(elm.style.left)||0, st=parseFloat(elm.style.top)||0;
      elm.classList.add('dragging');
      function mv(ev){
        var dx=(ev.clientX-startX)/fr.width*100;
        var dy=(ev.clientY-startY)/fr.height*100;
        var w=parseFloat(elm.style.width)||10;
        var hPct=elm.offsetHeight/fr.height*100;
        var nx=Math.max(0, Math.min(100-w, sl+dx));
        var ny=Math.max(0, Math.min(100-hPct, st+dy));
        elm.style.left=nx+'%'; elm.style.top=ny+'%';
      }
      function up(){
        elm.classList.remove('dragging');
        document.removeEventListener('pointermove', mv);
        document.removeEventListener('pointerup', up);
        commitMuseumLayout();
      }
      document.addEventListener('pointermove', mv);
      document.addEventListener('pointerup', up);
    });
    var rh=elm.querySelector('.mcase-resize');
    if (rh && !rh.__musBound){ rh.__musBound=true;
      rh.addEventListener('pointerdown', function(e){
        e.preventDefault(); e.stopPropagation();
        var fr=floor.getBoundingClientRect();
        var startX=e.clientX, sw=elm.getBoundingClientRect().width;
        elm.classList.add('dragging');
        function mv(ev){
          var nw=Math.max(70, Math.min(fr.width*0.62, sw+(ev.clientX-startX)));
          elm.style.width=(nw/fr.width*100)+'%';
        }
        function up(){
          elm.classList.remove('dragging');
          document.removeEventListener('pointermove', mv);
          document.removeEventListener('pointerup', up);
          commitMuseumLayout();
        }
        document.addEventListener('pointermove', mv);
        document.addEventListener('pointerup', up);
      });
    }
  });
}
function commitMuseumLayout(){
  var floor=document.querySelector('.museum-floor'); if(!floor) return;
  floor.querySelectorAll('.mcase-persp').forEach(function(elm){
    var cat=elm.getAttribute('data-cat')||elm.getAttribute('data-v');
    MUSEUM_LAYOUT[cat]={ x:parseFloat(elm.style.left)||0, y:parseFloat(elm.style.top)||0, w:parseFloat(elm.style.width)||10 };
  });
  saveMuseumLayout();
}

function renderCollectionMuseum(){
  var s=store.collection, f=ui.collection;

  /* 第 1 层：6 大类透视展厅（左侧 3 / 右侧 3，跟随背景透视走向） */
  if (!f.cat){
    var leftCats  = CATS.slice(0,3);   /* 手办 / 周边 / 杯盏 */
    var rightCats = CATS.slice(3,6);   /* 毛绒 / 卡牌 / 着物 */
    var h='<div class="museum">'+
      '<div class="wm-mask"></div>'+
      '<div class="mh">'+
        '<h1>藏 品 馆</h1>'+
        '<p>B R I T I S H   M U S E U M · E N L I G H T E N M E N T   G A L L E R Y</p>'+
        '<div class="musedit-bar">'+
          (f.editing
            ? '<button class="r-btn" data-act="musedit">✓ 完成布局</button>'+
              '<button class="r-btn ghost" data-act="musreset">重置布局</button>'+
              '<span class="musedit-hint">拖动展柜移动 · 拖右下角方块缩放</span>'
            : '<button class="r-btn" data-act="musedit">✎ 编辑布局</button>')+
          '<button class="r-btn" data-act="collclassic">经典列表 / 管理 IP · 系列</button>'+
        '</div>'+
      '</div>'+
      '<div class="museum-floor">'+
        '<div class="museum-side left">'+
          _renderPerspectiveCases(s.rows, leftCats, 'left', _museumCase)+
        '</div>'+
        '<div class="museum-side right">'+
          _renderPerspectiveCases(s.rows, rightCats, 'right', _museumCase)+
        '</div>'+
      '</div>'+
      '</div>';
    return h;
  }

  /* 第 2 层：某大类下的展柜（按小类聚合） */
  var cat=f.cat;
  var items=s.rows.filter(function(r){ return r['大类']===cat; });
  if (!f.sub){
    var subs={};
    items.forEach(function(r){ var k=r['小类']||'未分类'; (subs[k]=subs[k]||[]).push(r); });
    var subNames=Object.keys(subs);
    var h2='<div class="museum">'+
      '<div class="wm-mask"></div>'+
      '<div class="museum-crumb"><button class="r-back" data-act="mback">← 返回展厅</button>'+
        '<h2>'+esc(cat)+'</h2><span>'+items.length+' 件 · '+subNames.length+' 个展柜</span></div>'+
      '<div class="museum-grid">';
    subNames.forEach(function(sub){
      var arr=subs[sub];
      var thumbs=arr.slice(0,4).map(function(r){
        var u=coverImg(r);
        return u
          ? '<span style="background-image:url(\''+u.replace(/["'()\\]/g,'')+'\')"></span>'
          : '<span class="ph"></span>';
      }).join('');
      var gotN = (thumbs.match(/<span/g)||[]).length;
      for(var i=gotN; i<4; i++) thumbs += '<span class="ph"></span>';
      h2+='<div class="mcase glass-card" data-act="cabinet" data-v="'+esc(sub)+'">'+
        '<div class="zone-thumbs">'+thumbs+'</div>'+
        '<span class="ph"><b>'+esc(sub.slice(0,1))+'</b></span>'+
        '<h3>'+esc(sub)+'</h3>'+
        '<div class="meta"><span>展柜</span><span class="count">'+arr.length+' 件</span></div>'+
        '</div>';
    });
    h2+='</div></div>';
    return h2;
  }

  /* 第 3 层：展柜内部（所有藏品墙） */
  var sub=f.sub;
  var arr=s.rows.filter(function(r){ return r['大类']===cat && (r['小类']||'未分类')===sub; });
  var h3='<div class="museum">'+
    '<div class="wm-mask"></div>'+
    '<div class="museum-crumb"><button class="r-back" data-act="mback">← 返回 '+esc(cat)+' 展厅</button>'+
      '<h2>'+esc(cat)+' · '+esc(sub)+'</h2><span>'+arr.length+' 件</span></div>';
  if(!arr.length){
    h3+=emptyHTML('这个展柜还空着','点右上角「添加藏品」放一件进来。')+'</div>';
    return h3;
  }
  h3+='<div class="mcasewall">'+arr.map(museumItemCard).join('')+'</div></div>';
  return h3;
}

